const schedule = global.get("alarmSchedule");
const dayOfWeek = global.get("dayOfWeek");

if (!schedule || !schedule.days?.[dayOfWeek]) {
    return null;
}

// Get current date and time in Hungary
const now = new Date();

const formatter = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Europe/Budapest",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23"
});

const parts = formatter.formatToParts(now);
const get = type => parts.find(p => p.type === type).value;

const currentTime = `${get("hour")}:${get("minute")}`;
const today = `${get("year")}-${get("month")}-${get("day")}`;

// Check alarm time
if (currentTime !== schedule.time) {
    return null;
}

// Prevent duplicate triggers
const triggerKey = `${today}_${currentTime}`;

if (context.get("lastTriggered") === triggerKey) {
    return null;
}

context.set("lastTriggered", triggerKey);

// Trigger next chain
msg.payload = {
    event: "alarm",
    time: currentTime
};

return msg;

const alarmSchedule = global.get('alarmSchedule');
const [aHours, aMinutes] = alarmSchedule.time.split(":").map(Number);

const alarmTime = aHours*60 + aMinutes;

//today is yet to be done
const now = new Date();
const nowTime = now.getHours()*60 + now.getMinutes();
const todayDoneOffset = Number(nowTime > alarmTime);

// next days
let nextDays = todayDoneOffset;
const len = alarmSchedule.days.length;
let index = 0;
for (let i = 0; i < len; i++) {
    index = (global.get("dayOfWeek") + todayDoneOffset + i) % len;
    if (alarmSchedule.days[index]) break;
    nextDays++;
}

msg.payload = `${nextDays} days ${alarmSchedule.time}`;

return msg;

